const fs = require('fs');
const path = require('path');
const os = require('os');
const cp = require('child_process');
const sharp = require('sharp');
const { chromium } = require('playwright');

const ROOT = path.resolve(__dirname, '..', '..');
const FIG = path.join(ROOT, 'assets', 'figures');
const DRAW = path.join(ROOT, 'drawings');
const data = JSON.parse(fs.readFileSync(path.join(__dirname, 'two-answers.json'), 'utf8'));
const atlas = JSON.parse(fs.readFileSync(path.join(__dirname, 'spatial-atlas.json'), 'utf8'));
const context = JSON.parse(fs.readFileSync(path.join(__dirname, 'context-open-map.json'), 'utf8'));
const C = { ink: '#182320', graphite: '#65706c', green: '#176b55', green2: '#dbeae3', amber: '#df941d', amber2: '#f7e7c5', blue: '#176a99', blue2: '#d9eaf3', red: '#a44d43', paper: '#f4f0e6', white: '#fff', line: '#c4cbc6', dark: '#14201d' };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const L = (value, lang) => typeof value === 'string' ? value : value?.[lang] || '';
const scenario = (id) => data.scenarios.find((x) => x.id === id);
const station = (id) => atlas.stations.find((x) => x.id === id);
const heroIds = ['SCN-002', 'SCN-005', 'SCN-010'];

function svgCss() {
  return `text{font-family:'Segoe UI','Microsoft YaHei',Arial,sans-serif;fill:${C.ink}}.osm{fill:none;stroke:#cbd1cc;stroke-linecap:round;stroke-linejoin:round}.building{fill:#d9ded9;stroke:#c5ccc6;stroke-width:1}.park{fill:#e3eee5;stroke:none}.road_major{stroke:#b9c0bc;stroke-width:7}.road_local{stroke:#d0d5d2;stroke-width:3}.path{stroke:#d5d9d6;stroke-width:1.5}.rail{stroke:#919b96;stroke-width:5;stroke-dasharray:12 7}.water{stroke:#c9e1ea;stroke-width:10}.provisional{fill:none;stroke:${C.red};stroke-width:2;stroke-dasharray:11 9}.baseline{fill:none;stroke:${C.green};stroke-width:18;stroke-linecap:round;stroke-linejoin:round}.baseline-thin{fill:none;stroke:${C.green};stroke-width:9;stroke-linecap:round}.ai{fill:${C.amber2};stroke:${C.amber};stroke-width:6;stroke-dasharray:15 9}.evidence{fill:${C.blue};stroke:white;stroke-width:4}.evidence-box{fill:${C.blue2};stroke:${C.blue};stroke-width:4}.room{fill:#edf0ec;stroke:${C.ink};stroke-width:3}.buffer{fill:none;stroke:${C.red};stroke-width:5;stroke-dasharray:10 8}.remove{fill:none;stroke:${C.red};stroke-width:7;stroke-dasharray:15 9}.emergency{fill:none;stroke:${C.blue};stroke-width:7;stroke-dasharray:6 7}.title{font-size:30px;font-weight:900}.subtitle{font-size:15px;fill:${C.graphite}}.label{font-size:17px;font-weight:800}.small{font-size:12px;fill:${C.graphite}}.tiny{font-size:10px;fill:${C.graphite}}.hero-node{fill:${C.blue};stroke:white;stroke-width:4}.catalog-node{fill:white;stroke:${C.blue};stroke-width:3}.dimension{stroke:${C.graphite};stroke-width:1.5;marker-start:url(#arr);marker-end:url(#arr)}.dimtext{font-size:12px;fill:${C.graphite}}`;
}

function defs() { return `<defs><marker id="arr" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto"><path d="M8 0L0 4L8 8" fill="none" stroke="${C.graphite}"/></marker></defs>`; }
function points(arr) { return arr.map((p) => p.join(',')).join(' '); }
function contextLayer(id, minimal = false) {
  const c = context.contexts[id];
  return c.features.map((f) => {
    if (minimal && f.kind === 'road_local') return '';
    const tag = ['building', 'park'].includes(f.kind) ? 'polygon' : 'polyline';
    return `<${tag} class="osm ${f.kind}" points="${points(f.points)}"/>`;
  }).join('');
}

function overallSvg(lang = 'zh') {
  const zh = lang === 'zh';
  const stations = [
    ['zhongzhiyuan', 505, 205, '01', zh ? '众智园能力验证庭' : 'Zhongzhiyuan Validation Court', zh ? '环形测试庭＋完整旁路' : 'Loop court + complete bypass'],
    ['ai_origin', 500, 500, '02', zh ? 'AI 原点公共转译厅' : 'AI Origin Translation Hall', zh ? '可穿行大厅＋复核后台' : 'Porous hall + review back office'],
    ['dazhongsi', 510, 825, '03', zh ? '大钟寺城市采用场' : 'Dazhongsi Adoption Field', zh ? '交通前场＋独立试验湾' : 'Transit forecourt + separate trial bay'],
  ];
  let labels = '';
  stations.forEach((s, i) => {
    labels += `<line class="baseline-thin" x1="125" y1="${s[2] - 35}" x2="875" y2="${s[2] - 35}" stroke="${C.amber}" stroke-dasharray="12 9"/><line class="baseline-thin" x1="160" y1="${s[2] + 36}" x2="840" y2="${s[2] + 36}" stroke="${C.amber}" stroke-dasharray="12 9"/><circle cx="${s[1]}" cy="${s[2]}" r="55" fill="${C.paper}" stroke="${[C.green, C.amber, C.blue][i]}" stroke-width="9"/><circle cx="${s[1]}" cy="${s[2]}" r="20" fill="${[C.green, C.amber, C.blue][i]}"/><text x="${s[1] + 72}" y="${s[2] - 8}" class="label">${s[3]} ${esc(s[4])}</text><text x="${s[1] + 72}" y="${s[2] + 18}" class="small">${esc(s[5])}</text>`;
  });
  let nodes = '';
  data.scenarios.forEach((s, i) => {
    const p = i < 3 ? [440 + (i % 2) * 125, 135 + i * 58] : i < 6 ? [430 + (i % 2) * 140, 430 + (i - 3) * 58] : i < 9 ? [410 + (i % 2) * 175, 610 + (i - 6) * 55] : [430 + (i % 2) * 140, 775 + (i - 9) * 58];
    const klass = s.evidence_tier === 'hero' ? 'hero-node' : 'catalog-node';
    nodes += `<circle class="${klass}" cx="${p[0]}" cy="${p[1]}" r="${s.evidence_tier === 'hero' ? 17 : 11}"/><text x="${p[0] + (p[0] < 500 ? -20 : 20)}" y="${p[1] + 5}" text-anchor="${p[0] < 500 ? 'end' : 'start'}" class="${s.evidence_tier === 'hero' ? 'label' : 'small'}">${s.code}</text>`;
  });
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000"><style>${svgCss()}</style>${defs()}<rect width="1000" height="1000" fill="${C.paper}"/><g opacity=".7">${contextLayer('overall', true)}</g><rect class="provisional" x="105" y="28" width="790" height="940" rx="34"/><path class="baseline" d="M505 175 C470 330 530 415 500 500 S470 720 510 845" stroke-width="30"/><path d="M110 510H890" stroke="${C.amber}" stroke-width="10" stroke-dasharray="22 13"/><text x="125" y="485" class="label">${zh ? '中关村科技服务翼' : 'Technology Service Wing'}</text><text x="875" y="545" text-anchor="end" class="label">${zh ? '小月河场景赋能翼' : 'Scenario Enablement Wing'}</text>${labels}${nodes}<g transform="translate(42 875)"><rect width="365" height="90" rx="12" fill="white"/><line x1="18" x2="60" y1="22" y2="22" stroke="${C.green}" stroke-width="9"/><text x="73" y="27" class="small">${zh ? '连续公共基线' : 'Continuous civic baseline'}</text><circle cx="38" cy="51" r="9" class="hero-node"/><text x="73" y="56" class="small">${zh ? '3 个英雄场景' : '3 hero scenarios'}</text><circle cx="38" cy="76" r="7" class="catalog-node"/><text x="73" y="81" class="small">${zh ? '9 项复制索引' : '9-item replication catalogue'}</text></g><text x="950" y="966" text-anchor="end" class="tiny">© OpenStreetMap contributors · ODbL · 2026-08-13</text></svg>`;
}

