  const receipts = heroIds.map((id,i)=>{const s=scenario(id);return `<rect x="${70+i*505}" y="420" width="455" height="360" rx="16" fill="white" stroke="${[C.green,C.amber,C.blue][i]}" stroke-width="6"/><text x="${100+i*505}" y="470" class="title">${s.code} · ${esc(L(s.name,lang))}</text><text x="${100+i*505}" y="515" class="label">BASELINE → AI → EVIDENCE → HUMAN</text><text x="${100+i*505}" y="565" class="small">${zh?'零容忍停止：':'ZERO-TOLERANCE STOP:'}</text><foreignObject x="${100+i*505}" y="585" width="390" height="90"><div xmlns="http://www.w3.org/1999/xhtml" style="font:18px 'Segoe UI','Microsoft YaHei';line-height:1.35;color:${C.ink}">${esc(L(s.stop_conditions,lang))}</div></foreignObject><rect x="${100+i*505}" y="700" width="390" height="42" fill="${C.red}"/><text x="${295+i*505}" y="728" text-anchor="middle" style="font-size:18px;font-weight:900;fill:white">NOT FIELD-RUN · DECISION PENDING</text>`}).join('');
