  p.push(page(12, zh ? 'S2：详图、旅程与采纳回执' : 'S2: detail, journey and adoption receipt', L(scenario('SCN-005').operation_window, lang), `<div class="hero-combo"><div><div class="detail-box">${TA}</div>${journey('SCN-005', lang)}</div>${receipt('SCN-005', lang)}</div>`, lang));
