  p.push(page(14, zh ? 'S7：详图、旅程与采纳回执' : 'S7: detail, journey and adoption receipt', L(scenario('SCN-010').operation_window, lang), `<div class="hero-combo"><div><div class="detail-box">${TD}</div>${journey('SCN-010', lang)}</div>${receipt('SCN-010', lang)}</div>`, lang));
  p.push(page(15, zh ? '九项复制索引' : 'Nine-item replication catalogue', zh ? '其余场景不再平均占版面，但保持完整地址、组件、责任与退出链。' : 'The remaining scenes use less space while retaining address, components, ownership and exit trace.', `<div class="catalog-layout">${catalog(lang)}<div>${K}</div></div>`, lang));
  p.push(page(16, zh ? '六类画像与失败回退路径' : 'Six profiles and failure fallback', zh ? '每个人都先拥有普通路径；AI 失败时无需重新申请基本服务。' : 'Every person has the baseline first; AI failure never requires reapplying for basic service.', `<div class="persona-layout"><div class="persona-grid">${data.profiles.map((x, i) => `<article><b>${String(i + 1).padStart(2, '0')}</b><h3>${lang === 'zh' ? x.name_zh : x.name_en}</h3><p>${zh ? '普通服务 → 主动选择 → 人工复核 → 回退 → 申诉' : 'Baseline → opt in → human review → fallback → appeal'}</p></article>`).join('')}</div>${stationPlan('ai_origin', lang, true)}</div>${journey('SCN-005', lang)}`, lang));
